module mod_mult #(
    parameter n = 11,
    parameter delta = -1023,
    parameter modulus = 1025
)(
    input [n-1:0] a,
    input [n-1:0] b,
    input delta_a,
    input delta_b,
    output reg [n-1:0] p,
    output reg delta_p
);

    wire [2:0] AH = a[n-1:8];
    wire [2:0] AMH = a[7:5];
    wire [2:0] AML = a[4:2];
    wire [1:0] AL = a[1:0];
    wire [2:0] BH = b[n-1:8];
    wire [2:0] BMH = b[7:5];
    wire [2:0] BML = b[4:2];
    wire [1:0] BL = b[1:0];

    wire [n-1:0] pp_ll;
    wire [n-1:0] pp_lml;
    wire [n-1:0] pp_lmh;
    wire [n-1:0] pp_lh;
    wire [n-1:0] pp_mll;
    wire [n-1:0] pp_mlh;
    wire [n-1:0] pp_mlml;
    wire [n-1:0] pp_mlmh;
    wire [n-1:0] pp_mhl;
    wire [n-1:0] pp_mhh;
    wire [n-1:0] pp_mhml;
    wire [n-1:0] pp_mhmh;
    wire [n-1:0] pp_hl;
    wire [n-1:0] pp_hml;
    wire [n-1:0] pp_hmh;
    wire [n-1:0] pp_hh;

    logic_mod1025_minus_LL logic_ll (
        .address({AL, delta_a, BL, delta_b}),
        .data(pp_ll)
    );

    logic_mod1025_minus_LML logic_lml (
        .address({AL, delta_a, BML}),
        .data(pp_lml)
    );

    logic_mod1025_minus_LMH logic_lmh (
        .address({AL, delta_a, BMH}),
        .data(pp_lmh)
    );

    logic_mod1025_minus_LH logic_lh (
        .address({AL, delta_a, BH}),
        .data(pp_lh)
    );

    logic_mod1025_minus_MLL logic_mll (
        .address({AML, BL, delta_b}),
        .data(pp_mll)
    );

    logic_mod1025_minus_MLH logic_mlh (
        .address({AML, BH}),
        .data(pp_mlh)
    );

    logic_mod1025_minus_MLML logic_mlml (
        .address({AML, BML}),
        .data(pp_mlml)
    );

    logic_mod1025_minus_MLMH logic_mlmh (
        .address({AML, BMH}),
        .data(pp_mlmh)
    );

    logic_mod1025_minus_MHL logic_mhl (
        .address({AMH, BL, delta_b}),
        .data(pp_mhl)
    );

    logic_mod1025_minus_MHH logic_mhh (
        .address({AMH, BH}),
        .data(pp_mhh)
    );

    logic_mod1025_minus_MHML logic_mhml (
        .address({AMH, BML}),
        .data(pp_mhml)
    );

    logic_mod1025_minus_MHMH logic_mhmh (
        .address({AMH, BMH}),
        .data(pp_mhmh)
    );

    logic_mod1025_minus_HL logic_hl (
        .address({AH, BL, delta_b}),
        .data(pp_hl)
    );

    logic_mod1025_minus_HML logic_hml (
        .address({AH, BML}),
        .data(pp_hml)
    );

    logic_mod1025_minus_HMH logic_hmh (
        .address({AH, BMH}),
        .data(pp_hmh)
    );

    logic_mod1025_minus_HH logic_hh (
        .address({AH, BH}),
        .data(pp_hh)
    );

    wire [n:0] sum1, sum2, sum3, sum4;
    wire [n:1] carry1, carry2, carry3, carry4;
    wire [n-1:0] cout_vec1, cout_vec2, cout_vec3, cout_vec4;

    compressor4_2 comp0 (
        .x1(pp_ll[0]),
        .x2(pp_lml[0]),
        .x3(pp_lmh[0]),
        .x4(pp_lh[0]),
        .cin(1'b0),
        .sum(sum1[0]),
        .carry(carry1[1]),
        .cout(cout_vec1[0])
    );

    compressor4_2 comp1 (
        .x1(pp_mll[0]),
        .x2(pp_mlh[0]),
        .x3(pp_mlml[0]),
        .x4(pp_mlmh[0]),
        .cin(1'b0),
        .sum(sum2[0]),
        .carry(carry2[1]),
        .cout(cout_vec2[0])
    );

    compressor4_2 comp2 (
        .x1(pp_mhl[0]),
        .x2(pp_mhh[0]),
        .x3(pp_mhml[0]),
        .x4(pp_mhmh[0]),
        .cin(1'b0),
        .sum(sum3[0]),
        .carry(carry3[1]),
        .cout(cout_vec3[0])
    );

    compressor4_2 comp3 (
        .x1(pp_hl[0]),
        .x2(pp_hml[0]),
        .x3(pp_hmh[0]),
        .x4(pp_hh[0]),
        .cin(1'b0),
        .sum(sum4[0]),
        .carry(carry4[1]),
        .cout(cout_vec4[0])
    );

    genvar i;
    generate
        for (i = 1; i < 11; i = i + 1) begin : compressor_stage1
            compressor4_2 comp4 (
                .x1(pp_ll[i]),
                .x2(pp_lml[i]),
                .x3(pp_lmh[i]),
                .x4(pp_lh[i]),
                .cin(cout_vec1[i-1]),
                .sum(sum1[i]),
                .carry(carry1[i+1]),
                .cout(cout_vec1[i])
            );

            compressor4_2 comp5 (
                .x1(pp_mll[i]),
                .x2(pp_mlh[i]),
                .x3(pp_mlml[i]),
                .x4(pp_mlmh[i]),
                .cin(cout_vec2[i-1]),
                .sum(sum2[i]),
                .carry(carry2[i+1]),
                .cout(cout_vec2[i])
            );

            compressor4_2 comp6 (
                .x1(pp_mhl[i]),
                .x2(pp_mhh[i]),
                .x3(pp_mhml[i]),
                .x4(pp_mhmh[i]),
                .cin(cout_vec3[i-1]),
                .sum(sum3[i]),
                .carry(carry3[i+1]),
                .cout(cout_vec3[i])
            );

            compressor4_2 comp7 (
                .x1(pp_hl[i]),
                .x2(pp_hml[i]),
                .x3(pp_hmh[i]),
                .x4(pp_hh[i]),
                .cin(cout_vec4[i-1]),
                .sum(sum4[i]),
                .carry(carry4[i+1]),
                .cout(cout_vec4[i])
            );
        end
    endgenerate

    assign sum1[n] = cout_vec1[n-1];
    assign sum2[n] = cout_vec2[n-1];
    assign sum3[n] = cout_vec3[n-1];
    assign sum4[n] = cout_vec4[n-1];

    wire [n+1:0] sum5;
    wire [n+1:1] sum6;
    wire [n+1:1] carry5;
    wire [n+1:2] carry6;
    wire [n+1:0] cout_vec5, cout_vec6;

    compressor4_2 comp8 (
        .x1(sum1[0]),
        .x2(sum2[0]),
        .x3(sum3[0]),
        .x4(sum4[0]),
        .cin(1'b0),
        .sum(sum5[0]),
        .carry(carry5[1]),
        .cout(cout_vec5[0])
    );

    assign cout_vec6[0] = 1'b0;

    genvar j;
    generate
        for (j = 1; j < 12; j = j + 1) begin : compressor_stage2
            compressor4_2 comp9 (
                .x1(sum1[j]),
                .x2(sum2[j]),
                .x3(sum3[j]),
                .x4(sum4[j]),
                .cin(cout_vec5[j-1]),
                .sum(sum5[j]),
                .carry(carry5[j+1]),
                .cout(cout_vec5[j])
            );

            compressor4_2 comp10 (
                .x1(carry1[j]),
                .x2(carry2[j]),
                .x3(carry3[j]),
                .x4(carry4[j]),
                .cin(cout_vec6[j-1]),
                .sum(sum6[j]),
                .carry(carry6[j+1]),
                .cout(cout_vec6[j])
            );
        end
    endgenerate

    assign sum5[n+1] = cout_vec5[n];
    assign sum6[n+1] = cout_vec6[n];

    wire [n+2:1] sum7;
    wire [n+2:2] carry7;
    wire [n+1:1] cout_vec7;

    compressor3_2 comp11 (
        .x1(carry5[1]),
        .x2(sum5[1]),
        .x3(sum6[1]),
        .sum(sum7[1]),
        .cout(carry7[2])
    );

    assign cout_vec7[1] = carry7[2];

    genvar k;
    generate
        for (k = 2; k < 13; k = k + 1) begin : compressor_stage3
            compressor4_2 comp12 (
                .x1(sum5[k]),
                .x2(sum6[k]),
                .x3(carry5[k]),
                .x4(carry6[k]),
                .cin(cout_vec7[k-1]),
                .sum(sum7[k]),
                .carry(carry7[k+1]),
                .cout(cout_vec7[k])
            );
        end
    endgenerate

    assign sum7[n+2] = cout_vec7[n+1];

    wire [n-1:0] logic_data1;

    logic_rom_mult_minus_1_1025 logic_rom_1 (
        .address({sum7[n+2], carry7[n+2], sum7[n+1], carry7[n+1], sum7[n], carry7[n]}),
        .data(logic_data1)
    );

    wire [n-1:0] csa_sum;
    wire [n:1] csa_carry;

    csa #(
        .n(n+1)
    ) csa_0 (
        .a(logic_data1),
        .b({sum7[n-1:1], sum5[0]}),
        .c({carry7[n-1:2], 2'b0}),
        .sum_out(csa_sum),
        .carry_out(csa_carry)
    );

    wire [n:0] logic_data2;

    logic_rom_mult_minus_2_1025 logic_rom_2 (
        .address({csa_carry[n], csa_sum[n-1], csa_carry[n-1]}),
        .data(logic_data2)
    );

    wire [n-2:0] csa_sum2;
    wire [n-1:1] csa_carry2;

    csa #(
        .n(n)
    ) csa_1 (
        .a(logic_data2[n-2:0]),
        .b({csa_sum[n-2:0]}),
        .c({csa_carry[n-2:1], 1'b0}),
        .sum_out(csa_sum2),
        .carry_out(csa_carry2)
    );

    wire [n:0] y;
    wire delta_aux;
    assign y = {logic_data2[n-1], csa_sum2} + {csa_carry2, 1'b0};

    assign delta_aux = logic_data2[n] ^ y[n];

    always @(*) begin
        p = y[n-1:0];
        delta_p = delta_aux;
    end
endmodule
